import { h, icon } from './dom';
import { networkName } from './networks';

// Generated by scripts/logos.mjs. Importing them lets Vite hash them, so the page stays on 'self'.
// Sizes are data attributes, not inline styles: the CSP has no 'unsafe-inline'.
const FILES = import.meta.glob<string>('../logos/*.png', { eager: true, import: 'default' });

interface LogoSource {
  src: string;
  srcset: string;
}

function source(file: string): LogoSource | null {
  const x1 = FILES[`../logos/${file}-64.png`];
  const x2 = FILES[`../logos/${file}-128.png`];
  if (!x1 || !x2) return null;
  return { src: x1, srcset: `${x1} 1x, ${x2} 2x` };
}

const TOKEN_FILES: Record<string, string> = { USDC: 'usdc', USDT: 'usdt' };

const NETWORK_FILES: Record<string, string> = {
  base: 'base', solana: 'solana', ethereum: 'ethereum', arbitrum: 'arbitrum',
  optimism: 'optimism', polygon: 'polygon', bsc: 'bsc', avalanche: 'avalanche',
};

/** Test networks and the mainnet whose logo they reuse. */
const TESTNETS: Record<string, string> = {
  'base-sepolia': 'base',
  'solana-devnet': 'solana',
  'solana-testnet': 'solana',
  sepolia: 'ethereum',
  'ethereum-sepolia': 'ethereum',
  'arbitrum-sepolia': 'arbitrum',
  'optimism-sepolia': 'optimism',
  'polygon-amoy': 'polygon',
  'bsc-testnet': 'bsc',
  'avalanche-fuji': 'avalanche',
};

/**
 * How a logo sits on its circle. `ring` draws a hairline where the logo's own edge fades into
 * the surface (Solana, BNB and Arbitrum are near-black, Base and Ethereum near-white); `free`
 * logos are not round (the USDT diamond, the Polygon mark) and are never clipped to a circle.
 */
const LOOK: Record<string, { ring?: 'dark' | 'light'; free?: true }> = {
  solana: { ring: 'dark' },
  bsc: { ring: 'dark' },
  arbitrum: { ring: 'dark' },
  base: { ring: 'light' },
  ethereum: { ring: 'light' },
  usdt: { free: true },
  polygon: { free: true },
};

export interface NetworkInfo {
  chain: string;
  name: string;
  /** The mainnet whose logo is shown. */
  mainnet: string;
  testnet: boolean;
  logo: LogoSource | null;
  file: string | null;
}

export function networkInfo(chain: string): NetworkInfo {
  const id = chain.toLowerCase();
  const mainnet = TESTNETS[id] ?? id;
  const file = NETWORK_FILES[mainnet] ?? null;
  return { chain, name: networkName(chain), mainnet, testnet: id in TESTNETS, logo: file ? source(file) : null, file };
}

export interface TokenInfo {
  asset: string;
  logo: LogoSource | null;
  file: string | null;
}

export function tokenInfo(asset: string): TokenInfo {
  const file = TOKEN_FILES[asset.toUpperCase()] ?? null;
  return { asset, logo: file ? source(file) : null, file };
}

type LogoSize = 16 | 20 | 24;

export interface LogoOptions {
  size?: LogoSize;
  /** The name is printed next to the logo: hide the logo from assistive tech. */
  decorative?: boolean;
}

/** One logo on its circle, or the name's first letter when there is no file. Never a broken image. */
function logo(name: string, file: string | null, src: LogoSource | null, size: number, decorative: boolean): HTMLElement {
  const look = (file && LOOK[file]) || {};
  const wrap = h('span', {
    class: src ? 'logo' : 'logo logo-text',
    'data-logo': file ?? 'none',
    'data-ring': look.ring ?? null,
    'data-free': look.free ?? null,
    'data-size': size,
    'aria-hidden': decorative ? 'true' : null,
    role: !src && !decorative ? 'img' : null,
    'aria-label': !src && !decorative ? name : null,
  });
  if (src) {
    wrap.append(h('img', { src: src.src, srcset: src.srcset, alt: decorative ? '' : name, width: size, height: size, decoding: 'async' }));
  } else {
    wrap.textContent = name.trim().charAt(0).toUpperCase();
  }
  return wrap;
}

/** The visible "Testnet" tag next to a test network's logo: never colour alone. */
export function testnetTag(): HTMLElement {
  return h('span', { class: 'testnet-tag' }, 'Testnet');
}

export function tokenLogo(asset: string, { size = 20, decorative = false }: LogoOptions = {}): HTMLElement {
  const t = tokenInfo(asset);
  return logo(asset, t.file, t.logo, size, decorative);
}

export interface NetworkLogoOptions extends LogoOptions {
  /** Set false only where the caller prints the testnet tag itself. */
  tag?: boolean;
}

export function networkLogo(chain: string, { size = 20, decorative = false, tag = true }: NetworkLogoOptions = {}): HTMLElement {
  const n = networkInfo(chain);
  const mark = logo(n.name, n.file, n.logo, size, decorative);
  if (!n.testnet || !tag) return mark;
  return h('span', { class: 'logo-group' }, mark, testnetTag());
}

const CORNER: Record<LogoSize, number> = { 16: 8, 20: 10, 24: 14 };

/** The token logo with the network's logo at its lower right corner, for "USDC on Base". */
export function assetBadge(asset: string, chain: string, { size = 24, decorative = false, tag = true }: NetworkLogoOptions = {}): HTMLElement {
  const t = tokenInfo(asset);
  const n = networkInfo(chain);
  const label = `${asset} on ${n.name}`;
  const badge = h('span', {
    class: 'asset-badge',
    'data-size': size,
    role: decorative ? null : 'img',
    'aria-label': decorative ? null : label,
    'aria-hidden': decorative ? 'true' : null,
  }, logo(asset, t.file, t.logo, size, true), logo(n.name, n.file, n.logo, CORNER[size], true));
  badge.lastElementChild?.classList.add('logo-corner');
  if (!n.testnet || !tag) return badge;
  return h('span', { class: 'logo-group' }, badge, testnetTag());
}

/** Wallets with a bundled logo, matched on the EIP-6963 rdns, or on the name when there is no rdns. */
const WALLET_FILES: { file: string; rdns: string[]; name: string }[] = [
  { file: 'wallet-metamask', rdns: ['io.metamask'], name: 'metamask' },
  { file: 'wallet-rabby', rdns: ['io.rabby'], name: 'rabby' },
  { file: 'wallet-phantom', rdns: ['app.phantom'], name: 'phantom' },
];

export type WalletLogoSize = 20 | 28 | 36;

/**
 * A wallet's logo on a rounded tile: the bundled one for a known wallet, else a wallet outline.
 * The icon a wallet announces is a data: URL, which the page's CSP (img-src 'self') refuses.
 */
export function walletLogo(wallet: { rdns: string; name: string }, size: WalletLogoSize = 36): HTMLElement {
  const rdns = wallet.rdns.toLowerCase();
  const name = wallet.name.toLowerCase();
  const known = WALLET_FILES.find((w) => rdns
    ? w.rdns.some((r) => rdns === r || rdns.startsWith(`${r}.`))
    : name.includes(w.name));
  const src = known ? source(known.file) : null;
  const tile = h('span', { class: 'wallet-logo', 'data-size': size, 'data-logo': known?.file ?? 'none', 'aria-hidden': 'true' });
  tile.append(src ? h('img', { src: src.src, srcset: src.srcset, alt: '', width: size, height: size, decoding: 'async' }) : icon('wallet', Math.round(size * 0.6)));
  return tile;
}

/** Browser wallets offered when the page finds none, with their official download pages. */
export const WALLET_DOWNLOADS: { name: string; rdns: string; url: string }[] = [
  { name: 'MetaMask', rdns: 'io.metamask', url: 'https://metamask.io/download/' },
  { name: 'Rabby Wallet', rdns: 'io.rabby', url: 'https://rabby.io/' },
  { name: 'Phantom', rdns: 'app.phantom', url: 'https://phantom.com/download' },
];
